legacyCss:
.h1-1 {margin:0;padding:0;}
#feature-container-02 { background: url(/images/FEATURE/WEB_FEATURE_bg.png) bottom center no-repeat #00415e; -moz-background-size: cover; background-size: cover; color:#FFF;}
.feature_spacing { padding-top:2%; padding-bottom:5%;}
#feature_area { margin:0 auto; max-width:800px;}
.feature_obj { margin:0; padding:0; line-height:0; width:auto;}
.feature_obj_none { margin:0; padding:0; line-height:0; width:auto;}
.obj_show_area { padding:30px 20px 50px 20px;; min-height:230px; max-width:700px; margin:0 auto;}
.obj_ev_item { display:none;}
.overlay { position: absolute; top: 0; bottom: 0; left: 0; right: 0; height: auto; width: 100%; opacity: 0; transition: .5s ease; margin: 0 auto;}
.overlay:hover {}
.img-change { position:relative; width:auto; display:inline-block;}
.img-change:hover .overlay { opacity: 1;}
.obj_item_txt { color:#FFF; font-size:20px; padding-top:10px;}
.obj_item_title { color:#eddaa1; font-size:3rem; text-align:center; padding:0; margin-bottom:0;}
.obj_item_title span { display: block; position: relative; font-size: 3rem; font-weight:bold;}
.obj_item_title span:before,.obj_item_title span:after { content: ""; position: absolute; top: 50%; background: #eddaa1; width: 20%; height: 0px;}
.obj_item_title span:before { left: 5%;}
.obj_item_title span:after { right: 5%;}
@media (max-width: 767px) { #feature_area { margin-left:0;}
}
